var canPartition = function(nums) {
    let total = 0;
    for (const n of nums) total += n;
    if (total % 2 !== 0) return false;
    const target = total / 2;
    const dp = new Uint8Array(target + 1);
    dp[0] = 1;
    for (const n of nums) {
        for (let t = target; t >= n; --t) {
            if (dp[t - n]) dp[t] = 1;
        }
        if (dp[target]) return true;
    }
    return dp[target] === 1;
};
